 function hud(){if(!state)return;$('attack').disabled=!AttackCommand.fighterIds(state,selected).length;const ready=state.buildings.filter(b=>b.team===0&&b.hp>0).reduce((n,b)=>n+(b.readyGuns?.length||0),0);$('placeReadyGun').hidden=!ready;$('placeReadyGun').textContent='Geschütze platzieren ('+ready+')';const reporting=state.units.find(u=>selected.has(u.id));$('unitOrderInfo').textContent=reporting?'Auftrag: '+({guard:'Bereit',move:'Unterwegs',attack:'Angriff',enter:'Bemannen',board:'Einsteigen',repair:'Reparieren',attackBuilding:'Gebaeude angreifen',attackBridge:'Bruecke angreifen',repairBridge:'Bruecke reparieren'}[reporting.order]||reporting.order):'Einheit oder Fabrik auswaehlen';$('unitName').textContent=reporting?names[reporting.type]:'Keine Einheit';$('unitInfo').textContent=reporting?`${selected.size} / ${Math.ceil(reporting.hp)} HP / ${reporting.grenades} Granaten`:'Einheit oder Fabrik auswaehlen';const portrait=$('portrait').getContext('2d');portrait.imageSmoothingEnabled=false;portrait.clearRect(0,0,96,96);if(reporting)paintPortrait(portrait,reporting);const owned=[0,1].map(t=>state.sectors.filter(s=>s.owner===t&&s.countsForProduction!==false).length);$('status').textContent=`${Math.floor(state.time/60)}:${String(Math.floor(state.time%60)).padStart(2,'0')}   GEBIETE ${owned[0]} : ${owned[1]}   ${['LEICHT','NORMAL','SCHWER','BRUTAL'][difficulty]}`;$('selection').textContent=placement?'Linksklick: Geschütz setzen / Rechtsklick oder Esc: zurück':selected.size?`${selected.size} ausgewaehlt / ${classic?'Linksklick':'Rechtsklick'}: Befehl / U: Aussteigen`:`${classic?'Klassisch: Linksklick waehlt und befiehlt / Rechtsziehen scrollt':'Modern: Links waehlen / Rechts befehlen'}`;window.OriginalHud?.update(state,reporting,paintPortrait);factory();}
 function radarVisible(x,y){return BattlefieldVisibility.radarDetects(state.sectors,state.buildings,x,y);}
 function selectUnit(u,add=false,single=false){if(!add)selected.clear();const existing=customGroups.get(u.id);const group=single?[u]:state.units.filter(v=>v.team===0&&(existing?existing.has(v.id):v.squad===u.squad));for(const member of group){if(add&&selected.has(member.id))selected.delete(member.id);else selected.add(member.id);}lastSelection=[...selected];RadioAudio.say('select',{type:u.type});hud();}
 function cycle(category){if(!state)return;let entries=category==='building'?state.buildings.filter(b=>b.team===0&&b.hp>0):state.units.filter(u=>u.team===0&&(category==='hurt'?(hurt.get(u.id)||0)>performance.now():state.catalog.find(d=>d.type===u.type).class===category));if(!entries.length)return;const current=category==='building'?activeBuilding:[...selected][0],at=entries.findIndex(u=>u.id===current),entry=entries[(at+1)%entries.length];if(category==='building'){openFactory(entry);center(entry.x+entry.w/2,entry.y+entry.h/2);}else{selectUnit(entry);const p=unitPoint(entry);center(p.x,p.y);}}
 function center(x,y){cam.x=x-viewWidth()/zoom/2;cam.y=y-innerHeight/zoom/2;clamp();}
