  c.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);c.fillStyle='#172019';c.fillRect(0,0,viewWidth(),innerHeight);c.scale(zoom,zoom);c.translate(-cam.x,-cam.y);c.imageSmoothingEnabled=false;if(!OriginalArt.terrain(c,state.map))IndependentArt.terrain(c,state.map);drawPlacementTerritory();
  if(state.map.original){OriginalArt.objectShadows?.(c,state.objects||[],state.map);OriginalArt.flagShadows?.(c,state.sectors.filter(s=>!s.home&&s.countsForProduction!==false),state.time,state.map);}
  const m=state.map;for(let y=1;y<m.height;y++)for(let x=1;x<m.width;x++){const j=y*m.width+x,s=m.territory[j],owner=state.sectors[s].owner;c.fillStyle=owner===0?'#e86d53':owner===1?'#709de2':'#ddd1a0';if(m.territory[j-1]!==s)c.fillRect(x*32,y*32+12,2,2);if(m.territory[j-m.width]!==s)c.fillRect(x*32+12,y*32,2,2);}
  for(const u of state.units.filter(u=>selected.has(u.id))){c.save();c.lineWidth=1/zoom;c.strokeStyle='#eee2a58c';c.setLineDash([1/zoom,6/zoom]);c.beginPath();c.arc(unitPoint(u).x,unitPoint(u).y,state.catalog.find(d=>d.type===u.type).range||140,0,Math.PI*2);c.stroke();if(u.path?.length){c.strokeStyle='#f2dd92';c.setLineDash([2/zoom,4/zoom]);c.beginPath();c.moveTo(unitPoint(u).x,unitPoint(u).y);for(const p of u.path)c.lineTo(p[0],p[1]);c.stroke();}c.restore();}
  const mounted=new Set(state.map.original?state.buildings.flatMap(b=>OriginalArt.fortGuns(b,state.units).map(u=>u.id)):[]);const items=[...state.buildings.map(b=>({y:b.y+b.h,b})),...state.units.filter(u=>!mounted.has(u.id)).map(u=>({y:u.y,u})),...(state.map.original?(state.objects||[]).map(o=>({y:OriginalArt.objectDepth(o),o})):[]),...(state.map.original?state.crates.filter(box=>!box.taken).map(box=>({y:box.y,box})):[])].sort((a,b)=>a.y-b.y);for(const item of items){if(item.box){OriginalArt.crate(c,item.box,state.map);continue;}if(item.o){OriginalArt.object(c,item.o,state.map);continue;}if(item.b){if(!OriginalArt.building(c,item.b,state.time,state.map))IndependentArt.building(c,item.b,state.time);if(state.map.original)for(const u of OriginalArt.fortGuns(item.b,state.units))drawUnit(u);}else drawUnit(item.u);}
  for(const s of state.sectors){if(s.home||s.countsForProduction===false)continue;if(OriginalArt.flag(c,s,state.time,state.map))continue;c.fillStyle='#303a2c';c.fillRect(s.x,s.y-29,2,30);c.fillStyle=s.owner===0?'#de6141':s.owner===1?'#548cce':'#d7cfad';c.beginPath();c.moveTo(s.x+2,s.y-29);c.lineTo(s.x+20,s.y-27+Math.sin(state.time*4+s.id)*2);c.lineTo(s.x+17,s.y-17);c.lineTo(s.x+2,s.y-18);c.fill();}
