 function minimap(){const m=state.map,sx=mini.width/m.width,sy=mini.height/m.height;mc.fillStyle='#26392a';mc.fillRect(0,0,mini.width,mini.height);if(terrainOverlay&&state.map.original){mc.save();mc.scale(sx/32,sy/32);OriginalArt.terrain(mc,m);mc.restore();}else for(let y=0;y<m.height;y++)for(let x=0;x<m.width;x++){mc.fillStyle=terrainOverlay?['#a79263','#7e7b5a','#4c5141','#457d8a','#667047','#b3a478'][m.tiles[y*m.width+x]]:'#26392a';mc.fillRect(x*sx,y*sy,sx,sy);}if(zoneOverlay){mc.globalAlpha=.35;for(let y=0;y<m.height;y++)for(let x=0;x<m.width;x++){const owner=state.sectors[m.territory[y*m.width+x]].owner;if(owner<0)continue;mc.fillStyle=owner===0?'#e65238':'#5789d3';mc.fillRect(x*sx,y*sy,sx,sy);}mc.globalAlpha=1;}for(const b of state.buildings){mc.fillStyle=b.team===0?'#ed795a':b.team===1?'#689ee7':'#ddd5ad';mc.fillRect(b.x/32*sx,b.y/32*sy,b.w/32*sx,b.h/32*sy);}for(const radar of state.buildings.filter(b=>b.team===0&&b.kind==='radar'&&b.hp>0)){mc.strokeStyle='#d7db91';mc.beginPath();mc.ellipse((radar.x+radar.w/2)/32*sx,(radar.y+radar.h/2)/32*sy,BattlefieldVisibility.radarRadius(state.sectors,radar)/32*sx,BattlefieldVisibility.radarRadius(state.sectors,radar)/32*sy,0,0,Math.PI*2);mc.stroke();}for(const u of state.units)if(u.team===0||(u.team===1&&radarVisible(u.x,u.y))){mc.fillStyle=u.team===0?'#ff9d71':'#91beff';mc.fillRect(unitPoint(u).x/32*sx,unitPoint(u).y/32*sy,2,2);}mc.strokeStyle='#fff0bd';mc.strokeRect(cam.x/32*sx,cam.y/32*sy,viewWidth()/zoom/32*sx,innerHeight/zoom/32*sy);}

 function panMini(e){const r=mini.getBoundingClientRect();center((e.clientX-r.left)/r.width*state.map.width*32,(e.clientY-r.top)/r.height*state.map.height*32);}
 mini.onpointerdown=e=>{miniDrag=true;mini.setPointerCapture(e.pointerId);panMini(e);};mini.onpointerup=()=>miniDrag=false;mini.onpointercancel=()=>miniDrag=false;mini.onpointermove=e=>{if(miniDrag)panMini(e);if(!descriptions||!state){mini.title='';return;}const r=mini.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*state.map.width*32,y=(e.clientY-r.top)/r.height*state.map.height*32,b=state.buildings.find(b=>x>=b.x&&x<=b.x+b.w&&y>=b.y&&y<=b.y+b.h),u=state.units.find(u=>(u.team===0||radarVisible(u.x,u.y))&&unitHit(u,{x,y},40));mini.title=b?({fort:'FT',robot:'RF',vehicle:'VF',repair:'VR',radar:'RA'}[b.kind]):u?names[u.type]:'';};
 $('classic').onchange=()=>{classic=$('classic').value==='classic';hud();};$('cycleR').onclick=()=>cycle(0);$('cycleV').onclick=()=>cycle(1);$('cycleB').onclick=()=>cycle('building');$('cycleG').onclick=()=>cycle(2);$('portrait').onclick=()=>{const u=state?.units.find(u=>selected.has(u.id));if(u){const p=unitPoint(u);center(p.x,p.y);}};
 $('overlayT').onclick=()=>{terrainOverlay=!terrainOverlay;$('overlayT').classList.toggle('active',terrainOverlay);};$('overlayZ').onclick=()=>{zoneOverlay=!zoneOverlay;$('overlayZ').classList.toggle('active',zoneOverlay);};$('overlayD').onclick=()=>{descriptions=!descriptions;$('overlayD').classList.toggle('active',descriptions);};

 $('newBattle').onclick=()=>{if(state.winner===0)$('mission').value=Math.min(19,mission+1);start();};$('start').onclick=start;$('pauseButton').onclick=togglePause;$('resume').onclick=togglePause;$('quit').onclick=()=>{cancelPlacement();paused=true;menu=true;$('continueBattle').hidden=!state||state.winner!==null;window.MenuShell?.show('home');$('menu').hidden=false;$('pause').hidden=true;$('hud').hidden=true;RadioAudio.setScene('menu');};$('factoryClose').onclick=()=>{$('factory').hidden=true;activeBuilding=null;};$('cancelProduction').onclick=()=>{if(activeBuilding===null)return;update(call({op:'produce',id:activeBuilding,product:null}));const b=state.buildings.find(b=>b.id===activeBuilding);if(b?.product)RadioAudio.say('production',{type:b.product});};$('attack').onclick=beginAttackMode;$('stop').onclick=()=>command('stop');$('unload').onclick=()=>command('unload');$('speed').onclick=()=>{speed=speed===1?2:1;$('speed').textContent=speed+'x';};$('mute').onclick=()=>{muted=!muted;RadioAudio.mute(muted);$('mute').textContent=muted?'Ton aus':'Ton an';};
