 Promise.all([fetch(new URL('engine.wasm',sourceScript)).then(r=>{if(!r.ok)throw Error('Engine nicht erreichbar');return r.arrayBuffer();}).then(b=>WebAssembly.instantiate(b,{})),OriginalArt.load(),fetch(new URL('../original/campaign.json',sourceScript)).then(r=>r.ok?r.json():null),RadioAudio.load()]).then(([wasm,art,data,audio])=>{engine=wasm.instance.exports;campaign=data;if(!art||!campaign)throw Error('Originalpaket fehlt. Bitte Start-Spiel.cmd verwenden oder die private Spielseite oeffnen.');$('mission').replaceChildren();for(let i=0;i<campaign.missions.length;i++){const o=document.createElement('option');o.value=i;o.textContent=`${i+1} / ${campaign.missions[i].name}`;$('mission').append(o);}$('difficulty').querySelector('option[value="3"]')?.remove();$('start').disabled=false;$('loading').textContent=audio?'Originalkampagne, Grafik und Originalton bereit':'Originalkampagne und Originalgrafik bereit';RadioAudio.setScene('menu');}).catch(e=>$('loading').textContent=e.message);

